import{_ as t,o as e,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"🔬 科学日报 | 2026年6月23日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-06-23.md","filePath":"science-log/src/science-daily/2026-06-23.md"}'),a={name:"science-log/src/science-daily/2026-06-23.md"};function s(i,o,u,c,p,d){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="🔬-科学日报-2026年6月23日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年6月23日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年6月23日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年6月23日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第1期（2026-06-23）简讯 10 条（科学前沿 5 条 + AI 前沿 5 条） 分析日期：2026-06-23 版本：扩展版（10 条深度 + 交叉关联） 取证：CrossRef 逐条核验 5 篇 Science DOI 均命中（发布日期 2026-06-18）；arXiv API 核验 AI 前沿 4 条编号，第 5 条为多篇汇总且无稳定编号（详见该条）</p></blockquote><hr><h2 id="🌍-一、科学前沿" tabindex="-1">🌍 一、科学前沿 <a class="header-anchor" href="#🌍-一、科学前沿" aria-label="Permalink to &quot;🌍 一、科学前沿&quot;">​</a></h2><h3 id="_1-cd4-t-细胞的-双重打击-不只会指挥-还能断肿瘤的粮道" tabindex="-1">1. CD4+ T 细胞的&quot;双重打击&quot;：不只会指挥，还能断肿瘤的粮道 <a class="header-anchor" href="#_1-cd4-t-细胞的-双重打击-不只会指挥-还能断肿瘤的粮道" aria-label="Permalink to &quot;1. CD4+ T 细胞的&quot;双重打击&quot;：不只会指挥，还能断肿瘤的粮道&quot;">​</a></h3><p><strong>原文</strong>：芝加哥大学等机构的研究团队揭示了CD4+ T细胞抗癌的全新机制。研究发现，这些免疫细胞不仅扮演&quot;指挥官&quot;角色协调其他免疫细胞，更能直接对肿瘤发起攻击——通过分泌IL-3和TNF信号分子，它们能够特异性破坏肿瘤的血管系统，切断肿瘤的营养供应，从而抑制其生长和转移。</p><p><strong>深度扩展</strong>：</p><p>Cohen 用&quot;杀手与帮手&quot;两分法统治了肿瘤免疫学三十年：CD8+ T 细胞负责直接处决肿瘤细胞，CD4+ T 细胞负责发号施令。这篇发表于《Science》（2026-06-18 上线，DOI 10.1126/science.ads7910）的论文把这个二分法撕开了一道口子。第一作者 Lian Qiaoshi，全篇 14 位作者。</p><p>研究团队给出的机制不是&quot;CD4 也能杀细胞&quot;，而是一条更迂回的路径：肿瘤抗原特异性 CD4+ T 细胞并不直接接触肿瘤细胞，而是先召唤髓系细胞，再由髓系细胞拆掉肿瘤的血管。多重免疫荧光加上单细胞与组织转录组测序显示，CD4+ T 细胞会触发血管周围形成髓系细胞簇，簇内富含&quot;经典活化&quot;（classically activated）巨噬细胞；这些巨噬细胞在 T 细胞来源的白细胞介素-3（IL-3）刺激下大量产生肿瘤坏死因子（TNF），TNF 再对肿瘤血管造成损伤。</p><p>这条链条的意义在于&quot;可及性&quot;。肿瘤细胞本身高度异质、易逃逸；但肿瘤血管是相对稳定的公共基础设施，且其表面分子由宿主基因组编码，突变压力小。用免疫系统的力量去攻击一个不会进化的靶点，耐药性的演化出口被大幅压缩。这也解释了为何部分 CD8 主导的疗法在临床遇到天花板——缺了 CD4 这一环，血管这一层根本没被打开。</p><p><strong>跨主题关联</strong>：这属于&quot;攻击公共基础设施而非攻击个体&quot;的策略，与 <code>topics/biomedicine/index.md</code> 中的抗感染思路（靶向黏液酶保守区）同构；也可与 <code>topics/ai-system-architecture/index.md</code> 中&quot;依赖层被切断则上层整体失效&quot;的层间依赖分析对照阅读。</p><hr><h3 id="_2-大脑的-旋转波-皮层活动的涡旋拓扑" tabindex="-1">2. 大脑的&quot;旋转波&quot;：皮层活动的涡旋拓扑 <a class="header-anchor" href="#_2-大脑的-旋转波-皮层活动的涡旋拓扑" aria-label="Permalink to &quot;2. 大脑的&quot;旋转波&quot;：皮层活动的涡旋拓扑&quot;">​</a></h3><p><strong>原文</strong>：艾伦脑科学研究所的团队在Science发表的这项研究，首次揭示了大脑皮层中存在一种&quot;旋转波&quot;现象——神经活动以螺旋式模式在大脑中传播，形成全脑范围的地形协调。这种旋转波并非随机产生，而是遵循特定的空间拓扑结构，将不同脑区的活动紧密联系在一起。</p><p><strong>深度扩展</strong>：</p><p>这项研究（《Science》，2026-06-18，DOI 10.1126/science.adx1369，第一作者 Ye Zhiwen，11 位作者）做了一件此前只能靠理论猜测的事：把&quot;波&quot;从比喻变成解剖结构。</p><p>方法上是双模态：清醒小鼠的全皮层成像（cortex-wide imaging）加电生理记录，在多个空间尺度上同时捕捉活动传播。结果是一个反复出现的波型母题（motif）——波并不像石子入水的同心圆那样扩散，而是呈旋转/涡旋状，涡心稳定落在躯体感觉皮层，波前扫过整个躯体拓扑映射（somatotopic map，即身体各部位在皮层上的对应地图）。</p><p>更关键的是解剖学对应：感觉皮层内的轴突构筑本身就呈环形排布。也就是说，功能上看到的旋转波，在结构上有一条现成的&quot;环形跑道&quot;。三条旁证支撑这一解释：旋转波在两半球之间镜像对称；在感觉皮层与运动皮层之间也镜像；并与皮层下结构的放电同步。而最硬的一条是干预——双侧切断这条环形环路后，旋转波明显减弱。相关性至此升级为因果性。</p><p>为什么重要：信息如何在全脑整合，是神经科学的核心难题。旋转波提供了一个候选答案——它不依赖某个&quot;总控中枢&quot;，而是靠拓扑结构自组织的相位关系，把分散区域的时序绑定在一起。这直接关系到注意力与意识的绑定问题。</p><p><strong>跨主题关联</strong>：可与 <code>topics/neuroscience/index.md</code> 中的皮层动力学条目对读，&quot;结构决定可能的功能模式&quot;这一逻辑亦与 <code>topics/physics/index.md</code> 中的拓扑/相位讨论相通；对 <code>topics/ai-brain/index.md</code> 而言，这是一个&quot;无中央控制器也能全局同步&quot;的天然范例。</p><hr><h3 id="_3-cof-膜-用-分子筛-亲和-替代百年蒸馏" tabindex="-1">3. COF 膜：用&quot;分子筛 + 亲和&quot;替代百年蒸馏 <a class="header-anchor" href="#_3-cof-膜-用-分子筛-亲和-替代百年蒸馏" aria-label="Permalink to &quot;3. COF 膜：用&quot;分子筛 + 亲和&quot;替代百年蒸馏&quot;">​</a></h3><p><strong>原文</strong>：能源领域传来好消息！阿卜杜拉国王科技大学的研究团队成功开发出可规模化生产的共价有机框架（COF）膜，能够高效分离原油中的脂肪烃和芳香烃化合物。与传统蒸馏法相比，COF膜分离技术能够大幅降低能耗，同时提高产物纯度。</p><p><strong>深度扩展</strong>：</p><p>原油炼制的第一道工序，一个多世纪以来始终是蒸馏——按沸点切分馏分。它有效、成熟，但有两个结构性缺陷：能耗高（加热整塔物料），且精度不足（沸点相近但化学类别不同的组分难以干净分开）。</p><p>这篇《Science》论文（2026-06-18，DOI 10.1126/science.aea0869，第一作者 Cao Li，9 位作者）提出了另一条路径：不靠汽化潜热，靠孔道与化学亲和力的组合。团队制备的是结晶性共价有机框架（COF）膜，孔径被精确控制在微孔尺度，骨架则做了烷基官能化修饰。三件事同时在起作用——分子筛分（尺寸卡关）、优先亲和（烷基骨架更&quot;亲近&quot;脂肪烃）、以及电场辅助下的定向传输。三者叠加的结果是脂肪烃富集度超过 95%。</p><p>真正让这项工作从&quot;实验室漂亮数据&quot;变成&quot;工业候选&quot;的，是制备工艺：团队用电场辅助的卷对卷（roll-to-roll）工艺，连续制备出无缺陷的膜。卷对卷是卷材工业的通用语言，这意味着它天生具备放大潜力。论文报告在阿拉伯轻质原油体系中的渗透通量比无定形聚合物膜高出数个数量级。</p><p>意义：如果膜法能在通量与选择性上同时站住脚，炼化行业的能耗曲线会被整体下拉——因为分离而非反应，才是炼厂能耗的主要去处。这条路线也与&quot;用结构而非能量做功&quot;的一般规律一致。</p><p><strong>跨主题关联</strong>：可与 <code>topics/materials/index.md</code> 中多孔材料/膜分离条目对读；能耗侧的影响则接 <code>topics/space-energy/index.md</code> 与 <code>topics/wind-energy/index.md</code> 的&quot;单位产出能耗&quot;主线。</p><hr><h3 id="_4-母乳里的反式异油酸-母体饮食如何给新生儿免疫-编程" tabindex="-1">4. 母乳里的反式异油酸：母体饮食如何给新生儿免疫&quot;编程&quot; <a class="header-anchor" href="#_4-母乳里的反式异油酸-母体饮食如何给新生儿免疫-编程" aria-label="Permalink to &quot;4. 母乳里的反式异油酸：母体饮食如何给新生儿免疫&quot;编程&quot;&quot;">​</a></h3><p><strong>原文</strong>：芝加哥大学团队在Nature发表的后续研究表明，母体摄入的反式vaccenic酸（一种天然存在的反式脂肪酸，主要来源于奶制品和反刍动物脂肪）能够显著影响新生儿T细胞的发育，并留下深远的免疫&quot;印迹&quot;。</p><p><strong>深度扩展</strong>：</p><p>先更正一处来源标注：简讯写作&quot;在 Nature 发表&quot;，但 CrossRef 与 EuropePMC 均将该文归入《Science》（2026-06-18 上线，DOI 10.1126/science.aea4041，第一作者 Fan Hao，29 位作者）。&quot;后续研究&quot;的说法可能源于同一团队的前序工作，此处以可核验的 DOI 为准。</p><p>科学问题很朴素：母乳成分如何塑造新生儿免疫？反式异油酸（trans-vaccenic acid, TVA）是母乳中含量最高的天然反式脂肪酸，主要来自奶制品与反刍动物脂肪——注意它与人造反式脂肪在构型与代谢命运上并不相同，不能混为一谈。</p><p>研究做的是小鼠实验：给哺乳母鼠喂食富含 TVA 的饲料，其哺育的幼鼠体内初始 CD4+ T 细胞（naïve CD4+ T）群体显著扩增，对抗感染的自适应免疫能力增强。机制层面有两条线索：TVA 通过一条 G 蛋白偶联受体—CTCF 轴重编程新生初始 CD4+ T 细胞；并与特定转录因子协同，促使 Th1 方向极化。</p><p>值得强调的是&quot;时间窗&quot;这一层含义。同样的分子在成年个体体内可能只是代谢燃料，但在新生儿免疫系统尚在建立耐受与反应的边界时，它成了一个信号输入。所谓&quot;免疫印迹&quot;（immune imprinting），本质是发育早期的状态选择被固化下来——早期的一次偏置，会沿着后续发育路径自我强化。</p><p><strong>跨主题关联</strong>：可直接接 <code>topics/infant-care/index.md</code> 的婴幼儿营养与发育窗口讨论，并与 <code>topics/biomedicine/index.md</code> 中&quot;早期暴露决定长期表型&quot;的卫生假说线索对照。</p><hr><h3 id="_5-lucy-飞越-52246-donaldjohanson-一颗在翻滚的双叶小行星" tabindex="-1">5. Lucy 飞越 (52246) Donaldjohanson：一颗在翻滚的双叶小行星 <a class="header-anchor" href="#_5-lucy-飞越-52246-donaldjohanson-一颗在翻滚的双叶小行星" aria-label="Permalink to &quot;5. Lucy 飞越 (52246) Donaldjohanson：一颗在翻滚的双叶小行星&quot;">​</a></h3><p><strong>原文</strong>：NASA Lucy任务团队公布了其飞越(52246) Donaldjohanson小行星的最新数据。这颗直径约4公里的小行星呈现独特的双叶结构，更有趣的是，它以一种复杂的&quot;翻滚&quot;模式自转——两个叶片交替朝向观测者。</p><p><strong>深度扩展</strong>：</p><p>（尺寸需修正：论文给出的整体三维尺寸是 8.8 km × 4.4 km × 3.1 km，简讯的&quot;直径约 4 公里&quot;偏小。）</p><p>论文（《Science》，2026-06-18，DOI 10.1126/science.aec0503，第一作者 Marchi Simone，66 位作者——这是典型的大型任务论文）把 Lucy 飞越数据放进了天体演化的完整链条里。</p><p>第一环是身世：(52246) Donaldjohanson（DJ）位于主带，很可能是 Erigone 家族的成员。这意味着它不是一颗原初天体，而是约 1.55 亿年前一次碰撞中被撞碎的大天体的碎片。第二环是形态：DJ 由两个撞击坑密布的叶瓣组成，中间以较平滑的颈部相连——典型的接触双星（contact binary）结构，两颗子体在低速下并合。第三环是表面年龄：坑密度整体与 Erigone 家族的年龄相符，但直径小于 0.4 km 的小坑被优先抹平了，说明近期存在某种表面重置过程（细微尺度上的松动、滑动或尘埃覆盖）。</p><p>第四环最有趣：DJ 自转很慢，且处于翻滚（tumbling）状态——自转轴本身在进动。论文认为这可能源于辐射力导致的长期自旋减速（YORP 效应）。YORP 是一个纯粹的几何—热学耦合：不规则天体各面吸收阳光后以不同滞后重新辐射热量，净效果是产生力矩，长年累月地改变自旋状态。</p><p>为什么重要：Lucy 的目标是木星特洛伊小行星，DJ 只是路过的&quot;彩排&quot;。但这次飞越同时验证了两件事——探测器在高速相对运动下的成像与跟踪能力，以及&quot;主带碎片—双叶并合—辐射力矩驱动演化&quot;这一整套解释框架。它把一个遥远的家族史，变成了一串可测量的数字。</p><p><strong>跨主题关联</strong>：接 <code>topics/space-energy/index.md</code> 的小天体与行星演化条目，坑密度定年法的逻辑与 <code>topics/paleontology/index.md</code> 中的放射性定年同属&quot;用累积量反推时间&quot;。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-janusmesh-3–5-分钟生成双语义-3d-视觉错觉" tabindex="-1">6. JanusMesh：3–5 分钟生成双语义 3D 视觉错觉 <a class="header-anchor" href="#_6-janusmesh-3–5-分钟生成双语义-3d-视觉错觉" aria-label="Permalink to &quot;6. JanusMesh：3–5 分钟生成双语义 3D 视觉错觉&quot;">​</a></h3><p><strong>原文</strong>：国立阳明交通大学团队提出JanusMesh，一种无需训练的快速框架，通过跨空间双分支去噪和视图条件纹理合成，在3-5分钟内生成高真实感的双语义3D视觉错觉——从不同角度看是截然不同的物体。</p><p><strong>深度扩展</strong>：</p><p>双语义 3D 错觉是一个被低估的难题：要让<strong>同一个网格</strong>从两个不同视角读出<strong>两个完全不同的语义</strong>。这件事同时挑战几何与纹理，且两者互相拆台。</p><p>论文（arXiv 2606.20563，2026-06-18 提交，第一作者 Siang-Ling Zhang；简讯标注入选 ECCV 2026，arXiv 条目本身未载明会议）明确指出两条既有路线的失败模式。优化类方法慢，且颜色容易过饱和；&quot;朴素拼接&quot;类方法则根本做不出几何连贯性，接缝可见、语义互相泄漏（semantic leak）——从 A 视角看过去，B 的语义会渗出来。</p><p>JanusMesh 的解法是<strong>解耦成两个阶段</strong>，全程无需训练。第一阶段是跨空间双分支去噪（cross-space dual-branch denoising）：把 3D 潜变量动态解码到体素空间，在体素空间做 CLIP 引导的朝向对齐（orientation alignment）与有符号距离场（SDF）混合。在 SDF 上做融合而非在网格上拼接，是无缝的关键——SDF 是连续隐式场，两个子体的等值面天然平滑过渡，不产生硬接缝。第二阶段是视图条件纹理合成：把各视角的 2D 扩散先验投影、聚合到已融合的几何上，让每个视角看到的图案各自成立。</p><p>效果是 3–5 分钟，且在几何完整性与语义可辨识度上明显超过既有方法。真正的方法论启示在于：当任务里存在&quot;两个互相冲突的约束&quot;时，不要试图用一个模型同时满足，而要把它们分配到不同的表示空间（几何在 SDF，语义在 2D 先验），冲突就在表示层被吸收了。</p><p><strong>跨主题关联</strong>：这种&quot;冲突约束分派到不同表示层&quot;的手法，与 <code>topics/ai-system-architecture/index.md</code> 中的关注点分离原则同构；应用侧可接 <code>topics/game-dev/shadow-dungeon.md</code> 与 <code>topics/design/index.md</code> 的道具/空间设计工作流。</p><hr><h3 id="_7-memorywam-给机器人装上-可检索的长时记忆" tabindex="-1">7. MemoryWAM：给机器人装上&quot;可检索的长时记忆&quot; <a class="header-anchor" href="#_7-memorywam-给机器人装上-可检索的长时记忆" aria-label="Permalink to &quot;7. MemoryWAM：给机器人装上&quot;可检索的长时记忆&quot;&quot;">​</a></h3><p><strong>原文</strong>：香港中文大学、清华大学和浙江大学的联合团队开发了MemoryWAM，一种具有持久记忆的世界动作模型。该系统通过混合记忆设计，结合近期帧、事件边界锚点和总结性令牌，让机器人能够在长时域任务中做出更智能的决策。</p><p><strong>深度扩展</strong>：</p><p>世界动作模型（world action model, WAM）的卖点是同时预测&quot;视觉未来&quot;和&quot;动作&quot;，因此天生适合机器人操作。但它有一个被论文点破的根本性权衡：<strong>效率与记忆长度不可兼得</strong>。</p><p>推理高效的那一类，只条件于一个有界的近期观测窗口——本质上假设环境是马尔可夫的（当前观测已包含决策所需的全部信息）。真实世界不配合：东西被拿走了、门刚才开过、任务做到第三步。这类非马尔可夫场景下，窗口法必然失效。另一类保留完整历史，代价是时间与显存随序列长度大幅增长。</p><p>MemoryWAM（arXiv 2606.20562，2026-06-18 提交，第一作者 Sizhe Yang）的答案不是&quot;更长窗口&quot;，而是<strong>分层存储 + 定制注意力</strong>。混合记忆由三种成分构成：近期帧（细节、短期上下文）、事件边界锚点帧（在事件切换的时刻打桩，保留关键时刻的快照）、以及紧凑的 gist 令牌（把长程历史压缩成少数几个向量）。定制的注意力机制让模型能同时检索到&quot;细节的短期&quot;与&quot;压缩的长期&quot;。</p><p>这个设计在信息论上很干净：它承认并非所有历史都等价——事件边界处信息密度最高，中间过程可压缩。这也是人类记忆的运作方式：记住&quot;钥匙放在玄关&quot;这个结论，而不是记住放下钥匙的全过程视频。实验在仿真与真机的长时域、依赖记忆的操作任务上均超过强 VLA 与 WAM 基线，且推理延迟与显存占用更优。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code> 中&quot;记忆分层/压缩是认知效率的核心&quot;一条直接对应；工程实现侧可对照 <code>topics/ai-system-architecture/index.md</code> 的上下文管理策略。</p><hr><h3 id="_8-diffusiongemma-有多透明-把-黑箱-拆成两个可测的维度" tabindex="-1">8. DiffusionGemma 有多透明：把&quot;黑箱&quot;拆成两个可测的维度 <a class="header-anchor" href="#_8-diffusiongemma-有多透明-把-黑箱-拆成两个可测的维度" aria-label="Permalink to &quot;8. DiffusionGemma 有多透明：把&quot;黑箱&quot;拆成两个可测的维度&quot;">​</a></h3><p><strong>原文</strong>：Google团队深入研究了一个关键问题：扩散模型在连续潜空间中执行更多计算，这是否意味着其推理过程更难理解？通过变量透明度和算法透明度两个维度分解，研究者发现虽然扩散模型的不透明串行深度是自回归模型的28.6倍，但通过可解释的令牌瓶颈映射，可以将其降至仅1.1倍。</p><p><strong>深度扩展</strong>：</p><p>这是一个把&quot;可解释性&quot;从形容词变成数字的工作。论文（arXiv 2606.20560，2026-06-18 提交，第一作者 Joshua Engels；简讯标注 Google Research）提出了一个关键的方法论动作：先分解，再测量。</p><p>分解出的是两个维度。<strong>变量透明度</strong>（variable transparency）：我们是否理解模型计算状态的中间快照。<strong>算法透明度</strong>（algorithmic transparency）：能否用这些快照重建出模型到达输出的过程。前者是&quot;看得见&quot;，后者是&quot;看得懂&quot;。</p><p>朴素测量给出的结论很难看：DiffusionGemma 在连续潜空间里做大量计算，其&quot;不透明串行深度&quot;——介于两个可解释状态之间的串行计算量——初看是自回归 Gemma 4 的 <strong>28.6 倍</strong>。但这个数字有一个隐藏前提：潜空间状态被默认为不可解释。团队的第二个动作就是推翻这个前提：他们证明可以把去噪步之间的信息流映射到一个<strong>可解释的令牌瓶颈</strong>（interpretable token bottleneck）上，且下游性能没有任何下降。把中间状态视为可解释之后，不透明串行深度降到 Gemma 4 的 <strong>1.1 倍</strong>。</p><p>差距从 28.6 到 1.1，全部来自&quot;表示的选择&quot;，而非模型本身的改变。这是本篇最重要的启示：可解释性在相当程度上是测量框架的属性，不是模型的固有属性。</p><p>算法透明度则确实更难：扩散模型在每一步去噪中，画布上<strong>所有</strong>令牌预测都可能改变，这赋予了它实现复杂分布式算法的能力。团队用一组案例研究找到了扩散特有的新现象：非时序推理（non-chronological reasoning）、令牌与序列涂抹（token and sequence smearing）、中间上下文推理。最后测了可监控性（monitorability）——透明度最实用的下游应用——结论是 DiffusionGemma 与 Gemma 4 相当。</p><p><strong>跨主题关联</strong>：直接接入 <code>topics/ai-brain/index.md</code> 关于&quot;可解释性与可监控性&quot;的讨论，以及 <code>topics/ai-tools/index.md</code> 中的模型选型权衡；&quot;测量框架决定结论&quot;这一点亦与 <code>topics/philosophy/index.md</code> 的观察者依赖议题相通。</p><hr><h3 id="_9-timeprove-先提议、再验证——长视频时序推理的省钱打法" tabindex="-1">9. TimeProVe：先提议、再验证——长视频时序推理的省钱打法 <a class="header-anchor" href="#_9-timeprove-先提议、再验证——长视频时序推理的省钱打法" aria-label="Permalink to &quot;9. TimeProVe：先提议、再验证——长视频时序推理的省钱打法&quot;">​</a></h3><p><strong>原文</strong>：研究人员提出TimeProVe，一种针对长视频时序推理的成本高效混合框架。该方法先用轻量模块生成候选证据假设，再调用昂贵的视觉-语言模型进行定向验证，在保持7.3%性能提升的同时，将VLM调用减少75%、推理成本降低93%。</p><p><strong>深度扩展</strong>：</p><p>长视频问答（LVQA）的困境可以用一句话概括：<strong>证据是稀疏的，视频是冗长的</strong>。几个小时未剪辑的视频里，回答一个问题可能只需要其中 8 秒。</p><p>既有路线各有各的死法。密集处理：把整段视频喂给大型视觉-语言模型（VLM），计算成本高到不可承受。稀疏处理：先给视频分段打字幕，再在字幕上做推理——便宜，但会丢掉时间上高度局部化、且依赖运动本身的证据（&quot;他把杯子放下的<strong>那一瞬</strong>&quot;在字幕里几乎不可还原）。</p><p>TimeProVe（arXiv 2606.20561，2026-06-18 提交，第一作者 Arkaprava Sinha）采用&quot;提议—验证&quot;（propose-then-verify）的两段式结构，把昂贵资源集中投在少数候选上。第一段用轻量模块生成<strong>动作锚定</strong>的&quot;答案—证据&quot;假设；核心是其中的动作候选证据模块（Action-based Candidate Evidence, ACE），它把时间上局部化的动作转换成查询条件下的候选证据片段。第二段只对这几个候选片段调用昂贵 VLM 做定向验证。</p><p>数字很干脆：VLM 调用减少 75%，推理成本降低 93%，同时性能还提升 7.3%。</p><p>这里的结构性洞见是：<strong>不是所有帧都值得被同等对待，也不是所有推理都需要最强模型</strong>。把&quot;找证据&quot;（廉价、可并行的视觉/动作先验）与&quot;读证据&quot;（昂贵、需要语义理解）拆开，是这一类问题的通用解法。它也说明成本优化不必然牺牲精度——前提是廉价模块承担的是&quot;召回&quot;而非&quot;判断&quot;。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-tools/index.md</code> 中&quot;级联/路由降本&quot;的思路同源；<code>topics/ai-system-architecture/index.md</code> 里的&quot;贵组件只处理候选集&quot;模式可直接对照。</p><hr><h3 id="_10-icml-2026-港中深团队-6-篇入选-多篇汇总" tabindex="-1">10. ICML 2026 港中深团队 6 篇入选（多篇汇总） <a class="header-anchor" href="#_10-icml-2026-港中深团队-6-篇入选-多篇汇总" aria-label="Permalink to &quot;10. ICML 2026 港中深团队 6 篇入选（多篇汇总）&quot;">​</a></h3><p><strong>原文</strong>：香港中文大学（深圳）人工智能学院团队在ICML 2026共发表6篇论文，涵盖 RACER（风险感知的大模型路由框架，可减少58.6%模型调用）、B-PAC Reasoning（基于赌博理论的高效推理方法，降低81%推理计算）、MIMOMamba（矩阵值注意力机制，参数减少2/3仍达最优精度）、Romberg-ZOGE（高阶偏差缩减的零阶梯度估计器）、Semantic Router（针对MLLMs的对抗性扰动攻击研究）、SWE-ABS（对抗基准测试增强研究）。</p><p><strong>深度扩展</strong>：</p><p>这一条与前九条性质不同：它不是单篇论文，而是一组会议成果的汇总，简讯中未给出任何 DOI 或 arXiv 编号。<strong>已用 arXiv API 检索 RACER、MIMOMamba 等关键词，均无命中（0 条）</strong>，因此<strong>未能核实原始出处</strong>——不排除这些工作尚未预印本化、或标题在正式发表时发生了改动。以下仅就方向做方法论层面的梳理，不对具体数字背书。</p><p>六篇论文可以归成三个簇：</p><p><strong>其一，把&quot;调用&quot;变成可优化变量</strong>。RACER（风险感知的路由）与 Semantic Router 都属此列。前者的思路是：不同查询难度差异极大，用同一个大模型统一处理是浪费，因此先判断风险/难度再路由。后者把路由本身当作安全边界——对多模态大模型（MLLMs）施加对抗性扰动，考察路由决策是否可被诱导。两者合看，说明&quot;路由层&quot;已经从工程技巧升级为独立的研究对象，且它同时是成本问题与安全问题。</p><p><strong>其二，把&quot;计算&quot;从稠密改成稀疏</strong>。B-PAC Reasoning 借赌博机（bandit）框架做推理资源分配——把算力看作赌注，押在期望收益高的推理分支上。MIMOMamba 用矩阵值注意力（matrix-valued attention）替代向量值，在参数量减少约三分之二的条件下保持精度。两者的共同前提是：现有大模型在推理时存在大量冗余计算，冗余可以被结构性识别而非靠剪枝蛮力去除。</p><p><strong>其三，优化器的数学基础</strong>。Romberg-ZOGE 处理零阶梯度估计（zeroth-order gradient estimation）——在只能观测函数值、拿不到梯度的场景下的梯度近似。Romberg 的名字指向 Richardson/Romberg 外推：用不同步长的估计做高阶组合以消去低阶误差项。这类工作通常不显眼，但它是&quot;无梯度优化&quot;整条线的基础设施。</p><p><strong>方法论提示</strong>：本条的六个数字（58.6%、81%、2/3）应视为简讯转述，未获一次源确认。若后续需要引用，应等 ICML 2026 论文集（PMLR）上线后逐篇核对。</p><p><strong>跨主题关联</strong>：三条簇分别接 <code>topics/ai-system-architecture/index.md</code>（路由与级联）、<code>topics/ai-brain/index.md</code>（计算稀疏性）、<code>topics/cybersecurity/index.md</code>（对抗扰动与路由安全）。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="m1-cd4-t-细胞-→-il-3-→-血管周髓系簇-→-tnf-→-血管崩解-一条四段式因果链" tabindex="-1">M1. CD4+ T 细胞 → IL-3 → 血管周髓系簇 → TNF → 血管崩解：一条四段式因果链 <a class="header-anchor" href="#m1-cd4-t-细胞-→-il-3-→-血管周髓系簇-→-tnf-→-血管崩解-一条四段式因果链" aria-label="Permalink to &quot;M1. CD4+ T 细胞 → IL-3 → 血管周髓系簇 → TNF → 血管崩解：一条四段式因果链&quot;">​</a></h3><p>这是本期最完整的一条机制链，值得逐段拆开。核心结论是：肿瘤抗原特异性 CD4+ T 细胞并不直接杀死肿瘤细胞，而是通过<strong>重塑肿瘤血管</strong>间接抑制肿瘤生长（Science, 2026-06-18, DOI 10.1126/science.ads7910）。</p><p><strong>第一段：T 细胞的定位与分泌。</strong> 抗原特异性 CD4+ T 细胞被肿瘤抗原激活后，并非均匀散布在肿瘤实质中，而是聚集在血管周围。激活后的 CD4+ T 细胞分泌白细胞介素-3（IL-3）。IL-3 在经典免疫学中的角色主要是刺激造血祖细胞增殖分化，在抗肿瘤语境中长期被忽视——这正是本研究的破口：IL-3 在这里不是&quot;生长因子&quot;，而是&quot;招募信号&quot;。</p><p><strong>第二段：髓系细胞的定向募集与极化。</strong> IL-3 作用于髓系细胞（单核—巨噬谱系）。多重免疫荧光显示，血管周围形成了结构清晰的<strong>髓系细胞簇</strong>（perivascular myeloid cell clusters）。单细胞转录组进一步表明，簇内富含&quot;经典活化&quot;（classically activated，即 M1 样）巨噬细胞。关键点在于空间组织：不是散在的巨噬细胞，而是一个围绕血管的<strong>结构化聚集体</strong>。结构本身就是功能前提——TNF 必须高浓度、近距离地作用在血管壁上才有效，散在分泌会被稀释。</p><p><strong>第三段：TNF 的产生与血管损伤。</strong> 这些巨噬细胞在 IL-3 信号驱动下大量表达肿瘤坏死因子（TNF）。TNF 对血管内皮是一把双刃刀：低浓度促进炎症与黏附分子表达，高浓度则直接诱导内皮细胞凋亡、破坏内皮屏障、引起血管塌陷与血流中断。论文观察到的正是后者——血管损伤。</p><p><strong>第四段：后果。</strong> 血管被破坏 → 肿瘤供血中断 → 缺氧、营养匮乏 → 生长受抑、转移能力下降。</p><p><strong>为什么这条链重要：靶点的进化稳定性。</strong> 肿瘤细胞基因组高度不稳定，任何针对肿瘤细胞自身的抗原都可能因突变或表达下调而失效。但这条链上的关键执行者——血管内皮细胞与髓系细胞——由<strong>宿主基因组</strong>编码，突变率低、表观可塑性有限。攻击它们，等于攻击一个几乎不会&quot;进化出耐药性&quot;的靶点。同时也解释了临床上的一个悖论：某些以 CD8 为主导的疗法效果不达预期，可能因为缺少 CD4 这一环，血管这个&quot;总开关&quot;从未被打开。</p><p><strong>可检验预测</strong>：若机制成立，则在 CD4+ T 细胞缺失或 IL-3 信号被阻断的模型中，血管周髓系簇应消失、TNF 局部浓度应下降、肿瘤血管密度应上升；反之，外源补充 IL-3 或在肿瘤局部诱导髓系簇形成，应能重建抗肿瘤效应，且该效应可被抗 TNF 抗体逆转。</p><hr><h3 id="m2-旋转波、环形轴突与相位梯度-皮层如何自组织出涡旋" tabindex="-1">M2. 旋转波、环形轴突与相位梯度：皮层如何自组织出涡旋 <a class="header-anchor" href="#m2-旋转波、环形轴突与相位梯度-皮层如何自组织出涡旋" aria-label="Permalink to &quot;M2. 旋转波、环形轴突与相位梯度：皮层如何自组织出涡旋&quot;">​</a></h3><p>第二篇（Science, 2026-06-18, DOI 10.1126/science.adx1369）的价值在于，它把&quot;神经活动波&quot;从一个统计描述，钉在了具体的解剖结构与因果干预上。</p><p><strong>现象层。</strong> 清醒小鼠全皮层成像显示，神经活动并非以平面波或同心圆方式传播，而是频繁形成<strong>旋转（rotational）模式</strong>：存在一个相位奇点（涡心），波前绕该点旋转。涡心位置稳定集中在躯体感觉皮层，波前扫过躯体拓扑映射（somatotopic map）——即身体各部位在皮层上按顺序排列的那张&quot;地图&quot;。</p><p><strong>结构层。</strong> 为什么涡心在那里？答案在轴突构筑：感觉皮层内的轴突连接本身呈<strong>环形排布</strong>。这构成了一个闭合的传导环路。当一个行波沿闭合环路传播时，拓扑上必然产生相位绕数（winding number）——环路走一圈相位累积 2π，于是内部必然存在一个相位无定义的奇点。这就是涡心的数学来源：<strong>它不是被谁&quot;放置&quot;在那里，而是环形拓扑的必然产物</strong>。</p><p><strong>协调层。</strong> 三条镜像关系说明这不是局部巧合：旋转波在两半球间镜像对称；在感觉皮层与运动皮层之间也镜像；并与皮层下结构的放电节律同步。镜像意味着存在跨区域的相位锁定——两套环路的相位被绑定，形成更大尺度的协调。</p><p><strong>因果层。</strong> 最硬的一步：双侧切断这条环形环路，旋转波显著减弱。相关性由此升级为因果性——环路是旋转波的<strong>生成器</strong>，而不仅是它的载体。</p><p><strong>功能含义。</strong> 全脑信息整合长期缺少一个不依赖&quot;总控中枢&quot;的答案。旋转波提供了一个：靠拓扑与相位关系自组织。不同脑区不需要由某个中心逐一指挥，只要嵌入同一套相位场，其放电时序就自动被绑定。这正是&quot;绑定问题&quot;（binding problem）的一个候选解——意识的统一性可能来自相位的统一性，而非某个&quot;指挥席&quot;。</p><p><strong>可检验预测</strong>：若相位绑定是功能基础，则行为任务中需要跨区整合的时刻，应伴随旋转波相位相干性升高；人为诱导相位失锁（如光遗传扰动特定相位）应选择性破坏跨区整合，而不影响单区内加工。</p><hr><h3 id="m3-令牌瓶颈与不透明串行深度-可解释性作为可测量量" tabindex="-1">M3. 令牌瓶颈与不透明串行深度：可解释性作为可测量量 <a class="header-anchor" href="#m3-令牌瓶颈与不透明串行深度-可解释性作为可测量量" aria-label="Permalink to &quot;M3. 令牌瓶颈与不透明串行深度：可解释性作为可测量量&quot;">​</a></h3><p>第三篇（arXiv 2606.20560）的机制不在生物或物理世界，而在&quot;如何度量一个计算过程的可理解性&quot;。它给出的是一套可复用的度量装置。</p><p><strong>两个维度的定义。</strong></p><ul><li><strong>变量透明度（variable transparency）</strong>：能否理解模型计算状态的中间快照。问的是&quot;看得见吗&quot;。</li><li><strong>算法透明度（algorithmic transparency）</strong>：能否用这些快照重建出模型到达输出的完整过程。问的是&quot;看得懂吗&quot;。</li></ul><p>这一分解解决了此前讨论中最大的混乱：人们常把&quot;黑箱&quot;当成单一属性，实际上它至少是两个正交维度。一个模型可以状态可见但过程不可重建（看得见却看不懂），也可以过程可描述但状态不可读。</p><p><strong>核心度量：不透明串行深度。</strong> 定义为&quot;介于两个可解释状态之间的串行计算量&quot;。直觉是：如果模型的每一步中间状态都能读懂，那么它的推理就是逐步可追踪的；如果两步可读状态之间夹着大量不可读的串行计算，那这段就是&quot;黑箱深度&quot;。这一度量比&quot;参数量&quot;&quot;层数&quot;更贴近可解释性的实质，因为它直接量化了&quot;不可观测的计算跨度&quot;。</p><p><strong>测量结果与关键操作。</strong> 朴素测量下，DiffusionGemma 的不透明串行深度是自回归 Gemma 4 的 <strong>28.6 倍</strong>——这符合直觉：扩散模型在连续潜空间中反复迭代去噪，中间状态全是浮点张量，没有离散令牌可供阅读。但团队随后做了一个关键操作：把去噪步之间的信息流映射到一个<strong>可解释的令牌瓶颈</strong>上，并验证下游性能没有下降。这意味着潜空间状态可以被&quot;翻译&quot;成可读的离散表示，且这一翻译是无损的（就任务性能而言）。重新测量后，不透明串行深度降至 <strong>1.1 倍</strong>。</p><p><strong>这个数量级的落差说明了什么。</strong> 28.6 与 1.1 之间没有改变模型一个参数，改变的只是<strong>我们选择用什么表示来读它</strong>。因此结论是：可解释性在很大程度上是测量框架的属性，而非模型的固有属性。&quot;扩散模型不可解释&quot;这一判断，其实是一个表示选择造成的伪影。</p><p><strong>算法透明度的真正困难。</strong> 剩下的差距在算法层：扩散模型每一步去噪，画布上所有令牌的预测都可能同时改变。这赋予了模型实现复杂<strong>分布式算法</strong>的能力——计算不是沿一条链串行推进，而是在整个画布上并行协商。团队由此发现三个扩散特有现象：非时序推理（结论先于前提出现）、令牌与序列涂抹（信息在位置间弥散）、中间上下文推理（利用尚未定型的中间态作为工作记忆）。这些不是缺陷，而是与自回归模型本质不同的计算风格。</p><p><strong>下游检验。</strong> 可监控性（monitorability）是透明度最实用的出口：模型输出是否足以支撑下游监控任务。结论是 DiffusionGemma 与 Gemma 4 相当——即&quot;看起来更黑箱&quot;的模型，在实际可监控性上并不更差。</p><p><strong>可检验预测</strong>：若可解释性主要由表示选择决定，则对其他连续潜空间模型（如潜空间扩散语言模型、连续思维链模型）施加同类令牌瓶颈映射，应观察到类似的数量级收敛（数十倍 → 个位数倍）。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="p1-环流必有奇点-为什么-涡旋-在自然界反复出现" tabindex="-1">P1. 环流必有奇点：为什么&quot;涡旋&quot;在自然界反复出现 <a class="header-anchor" href="#p1-环流必有奇点-为什么-涡旋-在自然界反复出现" aria-label="Permalink to &quot;P1. 环流必有奇点：为什么&quot;涡旋&quot;在自然界反复出现&quot;">​</a></h3><p>皮层旋转波最容易被误读为&quot;大脑特有的巧妙设计&quot;。但从拓扑学看，它是<strong>必然的</strong>，甚至是无法避免的。</p><p>设一个二维介质上存在相位场 θ(x, y)，且该介质含有一条闭合传导环路。波沿环路传播意味着相位在环路上单调累积。绕行一周回到起点，物理状态必须自洽，因此相位累积必为 2π 的整数倍——这就是<strong>相位绕数（winding number）</strong> n。当 n ≠ 0 时，环路围成的区域内部必然存在至少一个点，其相位无定义（绕数不连续）——这就是<strong>相位奇点</strong>，物理上表现为涡心。</p><p>这个论证与介质是什么无关：超导体中的磁通涡旋、超流氦中的量子涡旋、流体力学中的涡丝、光学中的相位奇点、乃至星系旋臂，全都服从同一条拓扑约束。生物学没有&quot;发明&quot;旋转波，它只是碰巧拥有环形轴突环路，于是拓扑自动兑现了涡旋。</p><p><strong>可证伪预测</strong>：若这一解释正确，则涡心位置应严格由环路的几何中心（拓扑荷所在）决定，而非由外部输入决定——扰动感觉输入应改变波前传播方向与幅度，但不应把涡心推离环路几何中心；反之，若涡心可被随意驱离，则说明存在额外的主动定位机制，拓扑解释不充分。</p><p>同样的拓扑逻辑在 AI 侧也出现了：DiffusionGemma 的令牌瓶颈之所以能把 28.6 压到 1.1，本质是<strong>降低有效维度</strong>——把高维潜空间信息投影到低维可读流形而不丢失任务相关信息。低维不是妥协，而是可解释性的必要条件。</p><h3 id="p2-攻击守恒量-而非攻击变异体-一条演化逻辑" tabindex="-1">P2. 攻击守恒量，而非攻击变异体：一条演化逻辑 <a class="header-anchor" href="#p2-攻击守恒量-而非攻击变异体-一条演化逻辑" aria-label="Permalink to &quot;P2. 攻击守恒量，而非攻击变异体：一条演化逻辑&quot;">​</a></h3><p>为什么 CD4+ T 细胞—血管这条通路值得押注？答案不在免疫学，而在演化的第一性原理。</p><p>任何可自我复制的实体，在复制过程中必然产生变异。变异 + 选择 = 适应性演化。因此，<strong>凡是以&quot;个体&quot;为攻击靶点的策略，其有效性都随时间衰减</strong>——抗生素耐药、杀虫剂抗性、肿瘤靶向药耐药，都是同一支箭的三种落点。这是逻辑必然，不是技术缺陷。</p><p>但这条规律有一个前提：被攻击的对象必须<strong>能够复制、能够变异</strong>。肿瘤血管内皮细胞由宿主基因组编码，其增殖受宿主调控，其&quot;进化自由度&quot;远低于肿瘤细胞。髓系细胞同理。换言之，血管是肿瘤生态系统中的<strong>守恒量</strong>——它不参与肿瘤的体细胞演化博弈。</p><p>由此得到一条可推广的判据：<strong>在任何一个&quot;变异体 + 基础设施&quot;的两层系统中，针对基础设施的攻击具有更长的时间有效性</strong>，代价是可能误伤正常基础设施（因此需要空间选择性——这里靠的是&quot;肿瘤抗原特异性 CD4+ T 细胞&quot;提供的定位）。</p><p>这解释了三件事的同构：COF 膜用孔道结构而非热量做分离（结构是守恒的，热耗散是每批次都要重新支付的）；Lucy 的 YORP 效应用长期累积的辐射力矩改变自旋（累积量是守恒的，瞬时事件不是）；新生儿 TVA 暴露在时间窗内一次性写入免疫偏置，而成年后同一分子只是燃料（早期状态选择被固化，后期难以覆盖）。三者都是&quot;找到系统里那个不随每次运行而重置的量，并在它上面做功&quot;。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期十条看似分散，但共享一个统一逻辑：<strong>系统中的有效自由度远少于表面自由度，找到那个低维控制点，就能以极小代价撬动极大后果。</strong></p><p>逐个看就一目了然。CD4+ T 细胞的低维控制点不是肿瘤细胞（千万种突变），而是血管（一套结构）；旋转波的低维控制点是环形轴突环路（切断环路，波即消失）；COF 膜的低维控制点是微孔尺寸加烷基亲和（不靠加热整塔物料）；TVA 的低维控制点是新生儿那个有限的发育时间窗（成年后再补无效）；Lucy 的低维控制点是长期累积的辐射力矩（而不是某次撞击）；MemoryWAM 的低维控制点是事件边界帧（不是全部历史帧）；DiffusionGemma 的低维控制点是令牌瓶颈（不是整个潜空间轨迹）；TimeProVe 的低维控制点是少量候选证据片段（不是全部视频帧）；JanusMesh 的低维控制点是把几何与语义分派到不同表示空间（而不是让一个模型同时满足冲突约束）；ICML 那组工作的低维控制点是路由决策与稀疏计算分配。</p><p><strong>统一形式</strong>：一切&quot;高效&quot;都是&quot;找对了降维方式&quot;。这不是隐喻——它在数学上是同一件事：识别一个高维系统中真正承载因果的低维流形，然后把资源集中投在该流形上。期刊、领域、尺度全不同，但降维这个动作完全同构。</p><p>与库内已有主题的深层同构有三处。其一，<code>topics/cross-domain-synthesis-2026-q3.md</code> 归纳的&quot;约束—涌现&quot;与&quot;搜索空间—使能&quot;两个模式，在本期表现为&quot;约束（环路/孔道/时间窗）决定了可能的动力学，而识别约束即获得了使能&quot;——旋转波的涡心位置由环路几何约束决定，正是&quot;约束决定涌现形态&quot;的干净案例。其二，<code>topics/ai-brain/index.md</code> 的核心命题&quot;记忆是对历史的有损压缩&quot;，与 MemoryWAM 的 gist 令牌设计、DiffusionGemma 的令牌瓶颈是同一原理在两个层面的实现——一个在认知层面，一个在张量层面。其三，<code>topics/ai-system-architecture/index.md</code> 的层间依赖分析，与 CD4+ 链条&quot;切断下游公共层则上游全部失效&quot;的因果结构完全同构。</p><p>一条值得记住的反直觉推论：既然&quot;可解释性&quot;可以由表示选择决定（28.6 → 1.1），那么对知识库自身也应保持同样的怀疑——一个主题&quot;看起来混乱&quot;，往往只是因为它尚未被投影到合适的表示上，而非它本身无序。这也是外脑需要持续做自动关联的理由：关联就是在寻找那个让散点变成结构的投影。</p><hr><p>关键词：CD4+ T细胞, IL-3, TNF, 肿瘤血管, 旋转波, rotating waves, 相位奇点, winding number, 拓扑荷, 共价有机框架, COF 膜, 反式异油酸, trans-vaccenic acid, TVA, 免疫印迹, immune imprinting, 52246 Donaldjohanson, Lucy 探测器, Erigone 家族, YORP 效应, 接触双星, DiffusionGemma, 变量透明度, 算法透明度, 不透明串行深度, 令牌瓶颈, MemoryWAM, 世界动作模型, gist 令牌, JanusMesh, 双语义 3D 错觉, SDF 混合, TimeProVe, 长视频问答, 10.1126/science.ads7910, 10.1126/science.adx1369, 10.1126/science.aea0869, 10.1126/science.aea4041, 10.1126/science.aec0503, arXiv:2606.20560, arXiv:2606.20561, arXiv:2606.20562, arXiv:2606.20563, 芝加哥大学, 艾伦脑科学研究所, 阿卜杜拉国王科技大学, 香港中文大学, 清华大学, 浙江大学, 国立阳明交通大学, Google Research, NASA, Science, ICML 2026 关联：topics/biomedicine/index.md, topics/neuroscience/index.md, topics/infant-care/index.md, topics/materials/index.md, topics/space-energy/index.md, topics/paleontology/index.md, topics/physics/index.md, topics/quantum-physics/index.md, topics/ai-brain/index.md, topics/ai-system-architecture/index.md, topics/ai-tools/index.md, topics/cybersecurity/index.md, topics/philosophy/index.md, topics/design/index.md, topics/game-dev/shadow-dungeon.md, topics/science-news/index.md, topics/cross-domain-synthesis-2026-q3.md</p>',152)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
